def effective_limit(value, default=10):
    if value is None:
        return default
    elif value == 0:
        return 0
    elif isinstance(value, int) and value > 0:
        return value
    elif isinstance(value, int) and value < 0:
        raise ValueError("Negative limit not allowed")
    else:
        # Should handle other types if necessary, but based on requirements, we assume int or None
        return value
